"""Writes this user's labwc configuration from the Universe settings (called at login and after changes).

labwc only manages the windows (move, resize, minimise, maximise, close, Alt+Tab); everything you see besides
the windows is the Universe shell. The configuration lives in ~/.config/universe-os/labwc (labwc -C).
"""
import os
import subprocess
from xml.sax.saxutils import quoteattr

import config

AUTOSTART = '''#!/bin/sh
# Started by labwc for the Universe OS session (generated by universe-os; changes are overwritten).
# First the last picture of the login screen (the glowing core), so there is no black screen while the shell loads.
swaybg -m fill -c '#050815' -i /usr/share/universe-os/backgrounds/kern.png >/dev/null 2>&1 &
/usr/bin/universe-shell-supervisor &
dbus-update-activation-environment --systemd WAYLAND_DISPLAY XDG_CURRENT_DESKTOP XDG_SESSION_TYPE XKB_DEFAULT_LAYOUT XKB_DEFAULT_VARIANT LANG LANGUAGE >/dev/null 2>&1 &
xdg-user-dirs-update >/dev/null 2>&1 &
/usr/libexec/polkit-mate-authentication-agent-1 >/dev/null 2>&1 &
mako --config /usr/share/universe-os/mako.conf >/dev/null 2>&1 &
/usr/lib/universe-os/universe-idle &
/usr/lib/universe-os/universe-displays apply >/dev/null 2>&1
'''

RECOVERY_AUTOSTART = '''#!/bin/sh
# Herstelmodus: alleen een terminal, zonder de Universe-shell.
dbus-update-activation-environment --systemd WAYLAND_DISPLAY XDG_CURRENT_DESKTOP >/dev/null 2>&1
/usr/libexec/polkit-mate-authentication-agent-1 >/dev/null 2>&1 &
mako --config /usr/share/universe-os/mako.conf >/dev/null 2>&1 &
(sleep 1; notify-send "Universe OS herstelmodus" "De ruimtewereld is niet gestart. Typ 'universe-shell' om hem te proberen, of 'exit' en kies opnieuw inloggen.") &
xfce4-terminal --title "Universe OS herstelmodus" &
'''


# Window snapping like Windows (Axel, 12 Oct): Windows+arrows move a window between halves, quarters, maximised and
# minimised the way Windows does it. labwc only knows "snap to an edge" and "snap to a region"; the If queries ask
# where the window is now. tiled=left is a half from Windows+Left or from dragging to the left edge.
def _when(query, then, otherwise):
    return '<action name="If">%s<then>%s</then><else>%s</else></action>' % (query, then, otherwise)


def _region(name):
    return '<action name="SnapToRegion" region="%s"/>' % name


def _edge(direction):
    return '<action name="SnapToEdge" direction="%s"/>' % direction


def _snap_actions(direction):
    tiled = lambda d: '<query tiled="%s"/>' % d
    region = lambda r: '<query tiled_region="%s"/>' % r
    if direction == 'left':    # from the right half back to normal, from a right quarter to the left quarter
        return _when(tiled('right'), '<action name="UnSnap"/>',
               _when(region('top-right'), _region('top-left'),
               _when(region('bottom-right'), _region('bottom-left'), _edge('left'))))
    if direction == 'right':
        return _when(tiled('left'), '<action name="UnSnap"/>',
               _when(region('top-left'), _region('top-right'),
               _when(region('bottom-left'), _region('bottom-right'), _edge('right'))))
    if direction == 'up':      # a half becomes the upper quarter, a lower quarter the half, otherwise maximise
        return _when(tiled('left'), _region('top-left'),
               _when(tiled('right'), _region('top-right'),
               _when(region('bottom-left'), _edge('left'),
               _when(region('bottom-right'), _edge('right'), '<action name="Maximize"/>'))))
    # down: maximised -> back to normal, a half -> lower quarter, an upper quarter -> the half, otherwise minimise
    return _when('<query maximized="both"/>', '<action name="UnMaximize"/>',
           _when(tiled('left'), _region('bottom-left'),
           _when(tiled('right'), _region('bottom-right'),
           _when(region('top-left'), _edge('left'),
           _when(region('top-right'), _edge('right'), '<action name="Iconify"/>')))))


# Halves and quarters (dragging a window while holding Ctrl, Shift or the Windows key shows them; Windows+arrows use
# them for the quarters).
REGIONS = '''  <regions>
    <region name="left" x="0%" y="0%" width="50%" height="100%"/>
    <region name="right" x="50%" y="0%" width="50%" height="100%"/>
    <region name="top-left" x="0%" y="0%" width="50%" height="50%"/>
    <region name="top-right" x="50%" y="0%" width="50%" height="50%"/>
    <region name="bottom-left" x="0%" y="50%" width="50%" height="50%"/>
    <region name="bottom-right" x="50%" y="50%" width="50%" height="50%"/>
    <region name="center" x="15%" y="10%" width="70%" height="80%"/>
  </regions>'''


def _keybind(item):
    key = quoteattr(item['key'])
    extra = ' onRelease="yes"' if item.get('onRelease') else ''
    if item.get('snap'):
        return '    <keybind key=%s%s>%s</keybind>' % (key, extra, _snap_actions(item['snap']))
    if item.get('labwc'):
        direction = ' direction=%s' % quoteattr(item['direction']) if item.get('direction') else ''
        action = '<action name="%s"%s/>' % (item['labwc'], direction)
    else:
        action = '<action name="Execute" command=%s/>' % quoteattr(item['command'])
    return '    <keybind key=%s%s>%s</keybind>' % (key, extra, action)


def rc_xml(recovery=False):
    s = config.settings()
    binds = [_keybind(item) for item in config.shortcuts()]
    if recovery:
        binds = [b for b in binds if 'universe-ctl' not in b] + ['    <keybind key="C-A-t"><action name="Execute" command="xfce4-terminal"/></keybind>']
    return '''<?xml version="1.0"?>
<!-- Gegenereerd door Universe OS uit ~/.config/universe-os (sneltoetsen en instellingen). Wijzigingen hier worden overschreven. -->
<labwc_config>
  <core><decoration>server</decoration><gap>0</gap><adaptiveSync>no</adaptiveSync><reuseOutputMode>yes</reuseOutputMode></core>
  <placement><policy>cascade</policy></placement>
  <theme>
    <name>Universe</name><cornerRadius>10</cornerRadius><keepBorder>yes</keepBorder><dropShadows>yes</dropShadows>
    <titlebar><layout>icon:iconify,max,close</layout><showTitle>yes</showTitle></titlebar>
    <font place="ActiveWindow"><name>Noto Sans</name><size>10</size><weight>bold</weight></font>
    <font place="InactiveWindow"><name>Noto Sans</name><size>10</size></font>
    <font place="OnScreenDisplay"><name>Noto Sans</name><size>11</size></font>
  </theme>
  <windowSwitcher show="yes" preview="yes" outlines="yes" allWorkspaces="yes">
    <fields><field content="icon" width="6%%"/><field content="title" width="94%%"/></fields>
  </windowSwitcher>
  <focus><followMouse>no</followMouse><raiseOnFocus>no</raiseOnFocus></focus>
  <!-- Snapping like Windows: drag a window against the left or right edge for half the screen, against the top to
       maximise; the outline shows where it goes. Windows+arrows for halves and quarters. -->
  <snapping><range>12</range><overlay enabled="yes"><delay inner="150" outer="150"/></overlay><topMaximize>yes</topMaximize><notifyClient>always</notifyClient></snapping>
  <resistance><unSnapThreshold>20</unSnapThreshold></resistance>
  <!-- Every window edge can be dragged to make the window larger or smaller (wider grip than the visible border). -->
  <resize><popupShow>Never</popupShow><drawContents>yes</drawContents><minimumArea>10</minimumArea><cornerRange>14</cornerRange></resize>
%s
  <desktops number="1"/>
  <keyboard>
    <repeatRate>25</repeatRate><repeatDelay>600</repeatDelay>
%s
  </keyboard>
  <mouse><default/></mouse>
  <libinput>
    <device category="default">
      <naturalScroll>%s</naturalScroll>
      <tap>%s</tap>
      <pointerSpeed>%.1f</pointerSpeed>
    </device>
  </libinput>
</labwc_config>
''' % (REGIONS, '\n'.join(binds), 'yes' if s['naturalScroll'] else 'no', 'yes' if s['tapToClick'] else 'no', s['pointerSpeed'])


def environment():
    kb = config.keyboard()
    s = config.settings()
    lines = [
        'XKB_DEFAULT_LAYOUT=%s' % kb['layout'],
        'XKB_DEFAULT_VARIANT=%s' % kb['variant'],
        'XKB_DEFAULT_OPTIONS=compose:ralt' if kb['layout'] == 'us' and kb['variant'] != 'intl' else 'XKB_DEFAULT_OPTIONS=',
        'XCURSOR_THEME=Adwaita',
        'XCURSOR_SIZE=24',
        'MOZ_ENABLE_WAYLAND=1',
        'QT_QPA_PLATFORM=wayland;xcb',
        '_JAVA_AWT_WM_NONREPARENTING=1',
        'UNIVERSE_UI_SCALE=%d' % s['uiScale'],
    ]
    return '\n'.join(lines) + '\n'


def chrome_system_title_bar():
    """Google Chrome uses the Universe title bar (minimise, maximise, close) instead of its own, which only had a
    close button on Wayland (12 Oct). Chrome's "Use system title bar and borders" is a profile preference; it is set
    at login while Chrome is not running, and seeded for a profile that does not exist yet."""
    import json
    import subprocess
    base = os.path.join(os.environ.get('XDG_CONFIG_HOME') or os.path.expanduser('~/.config'), 'google-chrome')
    prefs = os.path.join(base, 'Default', 'Preferences')
    try:
        if subprocess.run(['pgrep', '-u', str(os.getuid()), '-x', 'chrome'], stdout=subprocess.DEVNULL).returncode == 0:
            return
        data = {}
        if os.path.exists(prefs):
            with open(prefs, encoding='utf-8') as f:
                data = json.load(f)
            if data.get('browser', {}).get('custom_chrome_frame') is False:
                return
        elif os.path.exists(base):
            return  # another profile layout: leave it alone
        data.setdefault('browser', {})['custom_chrome_frame'] = False
        os.makedirs(os.path.dirname(prefs), exist_ok=True)
        with open(prefs + '.universe', 'w', encoding='utf-8') as f:
            json.dump(data, f)
        os.replace(prefs + '.universe', prefs)
    except (OSError, ValueError):
        pass  # never block the login for this


def write(recovery=False):
    target = os.path.join(config.user_dir(), 'labwc-recovery' if recovery else 'labwc')
    os.makedirs(target, exist_ok=True)
    files = {
        'rc.xml': rc_xml(recovery),
        'environment': environment(),
        'autostart': RECOVERY_AUTOSTART if recovery else AUTOSTART,
        # No root menu: right-click on the space world belongs to the world.
        'menu.xml': '<?xml version="1.0"?>\n<openbox_menu><menu id="root-menu" label=""/></openbox_menu>\n',
    }
    for name, content in files.items():
        path = os.path.join(target, name)
        with open(path + '.tmp', 'w', encoding='utf-8') as f:
            f.write(content)
        os.replace(path + '.tmp', path)
    os.chmod(os.path.join(target, 'autostart'), 0o755)
    if not recovery:
        chrome_system_title_bar()
        window_buttons()
    return target


def window_buttons():
    """Minimise, maximise and close on windows that draw their own title bar (GTK 3/4 apps), like Windows. The schema
    default (90_universe-os.gschema.override) did not reach those apps through the settings portal, a user value does
    (VM, 12 Oct). Only Debian's default is replaced: a layout the user chose stays."""
    import subprocess
    key = ['org.gnome.desktop.wm.preferences', 'button-layout']
    try:
        current = subprocess.run(['gsettings', 'get'] + key, capture_output=True, text=True, timeout=5).stdout.strip()
        if current in ("'appmenu:close'", "':close'", "'appmenu:minimize,maximize,close'"):
            subprocess.run(['gsettings', 'set'] + key + ['appmenu:minimize,maximize,close'], timeout=5)
    except (OSError, subprocess.SubprocessError):
        pass


def reconfigure():
    write()
    if os.environ.get('LABWC_PID'):
        subprocess.run(['labwc', '--reconfigure'], check=False)


if __name__ == '__main__':
    import sys
    print(write(recovery='--herstel' in sys.argv))
